  @location(1) @interpolate(flat) vBanding: vec4<f32>,
  @location(2) @interpolate(flat) vGlyph: vec4<f32>,
  @location(3) @interpolate(flat) vColor: vec4<f32>,
  @builtin(front_facing) frontFacing: bool,
